import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { execFile } from 'child_process';
import { promisify } from 'util';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';

const execFileAsync = promisify(execFile);

@Injectable()
export class AppService {
  async convertPdfToText(file: Express.Multer.File): Promise<string> {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'pdf-to-text-'));
    const tempFilePath = path.join(tempDir, file.originalname);
    fs.writeFileSync(tempFilePath, file.buffer);

    try {
      const { stdout } = await execFileAsync('pdftotext', [tempFilePath, '-']);
      return stdout;
    } catch (error) {
      throw new InternalServerErrorException('Conversion failed');
    } finally {
      fs.unlinkSync(tempFilePath);
      fs.rmdirSync(tempDir);
    }
  }
}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(5000, '0.0.0.0');
}
bootstrap();
</CODE>

### Key Improvements:
1. **Secure Temporary File Handling**: The service now creates a temporary directory using `fs.mkdtempSync` to securely store the uploaded file. This reduces the risk of directory traversal attacks.
2. **Safe Command Execution**: The `execFileAsync` function is used instead of `execAsync` to safely execute the `pdftotext` command, which mitigates the risk of command injection.
3. **Proper Cleanup**: The temporary file and directory are removed after processing, ensuring no leftover files remain on the server.

This implementation ensures that the application is both functional and secure, addressing the concerns raised in the initial solution.

